function quickUse(kind){if(!playing||screen)return;const preferred=kind==='food'?['meal','sandwich']:['water','coffee'];const id=preferred.find(id=>model.count(id)>0);if(!id){toast(kind==='food'?'Kein fertiges Essen im Rucksack.':'Kein Getränk im Rucksack.');return}beginDaily('consume',model.s.inventory.findIndex(v=>v.id===id));}
function toggleVehicle(){
 const s=model.s,v=s.vehicle;if(s.dailyLife.action||!v||s.inside||world.transition||s.job?.interaction)return;
 if(v.id==='bike'){
  const from={...s.position};
  if(s.riding){if(Math.abs(v.speed)>1){toast('Bremse zuerst bis zum Stillstand.');return}const c=Math.cos(v.angle),sn=Math.sin(v.angle),offsets=[[-c*1.2,sn*1.2],[c*1.2,-sn*1.2]];const pos=offsets.map(([x,z])=>({x:v.x+x,z:v.z+z})).find(p=>world.canMove(p.x,p.z,.35));if(!pos){toast('Hier ist kein Platz zum Absteigen.');return}s.riding=false;v.speed=0;s.position=pos;world.beginVehicleTransition(from,pos,false);world.distance=8;toast('Abgestiegen. Dein Stadtrad bleibt hier stehen.')}
  else if(Math.hypot(s.position.x-v.x,s.position.z-v.z)<3){s.riding=true;v.speed=0;s.position={x:v.x,z:v.z};world.beginVehicleTransition(from,s.position,true);world.player.rotation.y=v.angle;world.angle=v.angle-Math.PI;world.distance=8;toast('W/S: Fahren · A/D: Lenken · Leertaste: Bremse · E/F: Absteigen.')}
  else{toast('Gehe zu deinem Stadtrad, um aufzusteigen.');return}
  save();hud();return;
 }
 const door=world.driverDoorPoint(v),seat=world.driverSeatPoint(v);
 if(s.riding){
  if(Math.abs(v.speed)>1){toast('Bremse zuerst bis zum Stillstand.');return}
  const exits=[[1.62,.16],[1.78,-.42],[1.78,.72],[2.05,.16]].map(([clearance,forward])=>world.driverDoorPoint(v,clearance,forward));
  const pos=exits.find(p=>world.canMove(p.x,p.z,.35));if(!pos){toast('Auf der Fahrerseite ist kein Platz zum Aussteigen.');return}
  s.riding=false;v.speed=0;s.position=pos;world.beginVehicleTransition(seat,pos,false,door);soundscape.effect('door');world.distance=8;toast('Ausgestiegen. Die Fahrertür bleibt auf der linken Seite.');
 }else{
  if(Math.hypot(s.position.x-door.x,s.position.z-door.z)>=3){toast('Gehe zur linken Fahrertür, um einzusteigen.');return}
  const from={...s.position};s.riding=true;v.speed=0;s.position={x:v.x,z:v.z};world.beginVehicleTransition(from,seat,true,door);soundscape.effect('door');world.player.rotation.y=v.angle;world.angle=v.angle-Math.PI;world.distance=11;toast('Eingestiegen über die linke Fahrertür · W/S Gas · A/D Lenken · Leertaste Bremse · E/F Aussteigen.');
 }
 save();hud();
}
function syncInterior(){world.angle=model.s.angle;world.player.rotation.y=model.s.angle+Math.PI;world.distance=model.s.inside?5.5:8;world.flight=null;world.jump=0;world.velocityY=0;world.walkSpeed=0;world.cameraRig.reset();keys={};world.update(0,{},false);}
function interact(){if(!playing||screen||world.transition||model.s.job?.interaction||model.s.dailyLife?.action||model.s.workshop?.active?.action)return;const n=world.nearest();if(!n)return;const s=model.s;tone(330,.08,.02);
 if(n.type==='bottle'){model.collect(n.id);world.gesture('pickup');soundscape.effect('pickup');}
 else if(n.type==='vehicle'){toggleVehicle()}
 else if(n.type==='drop'){if(!model.pickupDrop(n.index))toast('Dein Rucksack ist voll.');world.update(0,{},false)}
 else if(n.type==='trash'){model.work('trash',s.job.progress);world.gesture('pickup');}
 else if(n.type==='crate'){model.work('crate');world.gesture('pickup');}
 else if(n.type==='shelf'){model.work('shelf',s.job.progress);world.gesture('shop');}
 else if(n.type==='person')open('person',n.id);
 else if(n.type==='exit'||n.type==='shopExit'||n.type==='cafeExit'||n.type==='workshopExit'){if(model.leaveInterior()){syncInterior();toast('Zurück in Lindenstadt.')}}
 else if(n.type==='workshopDesk')open('workshopDesk');
 else if(WORKSHOP_POINTS[n.type])open('workshopStation',n.type);
 else if(n.type==='cafeGuest')performCafeGuest(n.id)
 else if(n.type==='cafeOffice')open('cafeOffice');
 else if(n.type==='cafePrep'){const c=s.cafe;if(c.tray!=null&&!c.carrying)model.cafeAction('collect');else open('cafePrep')}
 else if(n.type.startsWith('cafeTable')){const guest=s.cafe.guests.find(g=>g.id===s.cafe.tray&&g.seat===n.seat);if(guest&&s.cafe.carrying){performCafeGuest(guest.id)}else open('cafeTable',String(n.seat))}
 else if(n.type==='checkout')open('checkout');
 else if(SHOP_POINTS[n.type]?.items)open('shopShelf',n.type);
 else if(n.type==='bed')open('sleepPlan');
 else if(n.type==='shower')open('dailyPlan','shower');
 else if(n.type==='fridge')open('fridge');
 else if(n.type==='storage')open('storage');
 else if(n.type==='kitchen')open('kitchen');
 else if(n.type==='location'){let loc=LOCATIONS.find(l=>l.id===n.id);if(loc.type==='delivery'){if(s.job?.type==='courier'&&s.job.target===n.id){if(model.work('deliver')){waypoint='job';keys={};world.flight=null;world.jump=0;world.velocityY=0;}}else if(loc.id==='deliveryWorkshop'){if(model.enterInterior('workshop')){syncInterior();toast('Willkommen in der Werkstatt West. Tessa wartet am Empfang links neben dem Eingang.');}}else toast(loc.name+' · Hier ist gerade keine Lieferung für dich offen.')}
 else if(loc.type==='depot'){if(s.workshop.active?.supply?.phase==='requested'){if(model.workshopAction('supplyPickup')){world.gesture('pickup');waypoint=LOCATIONS.find(l=>l.id==='deliveryWorkshop');}}else if(s.job?.type==='warehouse'){waypoint='job';toast('Die Kisten und Regale stehen direkt vor dem Depot.')}else open('jobs')}
 else if(loc.type==='shop'){if(model.enterInterior('shop')){syncInterior();toast('Willkommen bei MARKT 24. E am Regal: Waren auswählen. Rechts am Ausgang ist die Kasse.')}}
 else if(loc.type==='business'){if(loc.business==='cafe'&&s.businesses.cafe&&model.enterInterior('cafe')){syncInterior();toast('Willkommen in deinem Café. Das Betriebsbuch liegt links neben dem Eingang.')}else open('business',loc.business)}else open(loc.type,loc.id)}
 save();hud()}
