 if(a==='fridgeTransfer'){const [direction,index]=arg.split('|');if(model.fridgeTransfer(Number(index),direction))world.gesture('shop');save();renderModal();return;}

 if(a==='close'){close();return}if(a==='continue'){if(saved)startGame(structuredClone(saved));return}
 if(a==='new'||a==='sandbox'){let mode=a==='sandbox'?'sandbox':'story';if(saved||playing)open('confirmNew',mode);else startGame(newGame(mode==='sandbox'));return}
 if(a==='confirmedNew'){startGame(newGame(arg==='sandbox'));return}
 if(a==='interact'){interact();return}
 if(a==='inventory'){category='Alle';selected=0;open('inventory');return}
