 if(a==='navigate'){waypoint=LOCATIONS.find(l=>l.id===arg);close();toast('Ziel markiert: '+waypoint.name);return}
 if(a==='navigatePerson'){waypoint=PEOPLE.find(p=>p.id===arg);close();return}
 if(a==='trackQuest'){let q=QUESTS[model.s.quest];if(q){waypoint='quest';toast('Ziel markiert.')}hud();return}
 if(a==='trackJob'){waypoint='job';close();return}
