 if(a==='cook'){open('dailyPlan','cook|'+arg);return;}
 if(a==='quickFood'){quickUse('food');return}if(a==='quickDrink'){quickUse('drink');return}
 if(a==='use'){beginDaily('consume',Number(arg));return;}if(a==='drop')model.drop(Number(arg));if(a==='dropAll')model.drop(Number(arg),true);if(a==='split')model.split(Number(arg));
 if(a==='basketAdd'&&model.basketAdd(arg)){world.gesture('shop');soundscape.effect('shop');}if(a==='basketRemove')model.basketRemove(arg);if(a==='checkout'){if(model.checkout()){world.gesture('shop');soundscape.effect('checkout');close();}}
 if(a==='buy')model.buy(arg);if(a==='recycle')model.recycle();
