 if(a==='courierFilter'){courierFilter=['all','relaxed','express'].includes(arg)?arg:'all';renderModal();return}
 if(a==='acceptContract'){const [id,mode]=arg.split('|');if(model.acceptContract(id,mode||'foot')){waypoint='job';keys={};world.flight=null;world.jump=0;world.velocityY=0;close()}}
 if(a==='startJob'){if(model.s.inside||model.s.riding||!['jobs','depot'].some(id=>{const l=LOCATIONS.find(l=>l.id===id);return Math.hypot(l.x-model.s.position.x,l.z-model.s.position.z)<3.1})){toast('Nimm die Schicht vor Ort bei Kiez & Kurier oder am Depot an.');return}if(model.startJob(arg)){waypoint='job';close()}}
 if(a==='cancelJob'){model.cancelJob();waypoint=null;open('tour')}
 if(a==='sleep'){open(arg==='home'?'sleepPlan':'dailyPlan',arg==='home'?'':'shelterSleep');return;}
 if(a==='freeWater'){model.s.needs.thirst=100;model.emit('Trinkwasser aufgefüllt.','success')}
 if(a==='wash'){open('dailyPlan','wash');return;}
 if(a==='reviewRent'){open('reviewRent',arg);return;}
 if(a==='rent'){if(model.moveHome(arg)){open('housing',homeLocation(model.s).id);save();hud();}return;}
 if(a==='enterHome'){if(model.enterInterior('home')){syncInterior();close();toast('Dein Zuhause. Der grüne Ausgang ist hinter dir. E zum Interagieren.')}}
 if(a==='course'){plannedAction={arg,minutes:arg==='logistics'?180:240};open('timeConfirm');return;}
