 if(a==='cafeGuest'){if(performCafeGuest(Number(arg)))close()}
 if(a==='cafeClean'){if(model.cafeAction('clean',Number(arg))){world.gesture('cafeClean');close()}}
 if(a==='cafePrepare'){if(model.cafeAction('prepare',Number(arg)))close()}
 if(a==='cafeCollect'){if(model.cafeAction('collect'))close()}
 if(a==='manage'){const [id,op,val]=arg.split('|');model.manage(id,op,val)}
 if(a==='bankAction'){let value=Number($('bankAmount')?.value)*100;if(value>0)model.bank(arg,value);else toast('Gib einen positiven Betrag ein.');}
 if(a==='confirmLoan'){const value=Math.round(Number($('bankAmount')?.value)*100);if(value>0)open('confirmLoan',String(value));else toast('Gib einen positiven Betrag ein.');return}
 if(a==='loan'){model.bank('loan',Number(arg));open('bank')}
