 if(a==='export'){const s=playing?model.s:saved;if(!s){toast('Es gibt noch keinen Spielstand.');return}const blob=new Blob([JSON.stringify(s,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download='ZERO-RISE-Tag-'+s.day+'.json';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Spielstand als Datei exportiert.','success');return}
