document.addEventListener('input',e=>{if(['sensitivity','brightness','fov','ambienceVolume','vehicleVolume','effectsVolume'].includes(e.target.id)){model.s.settings[e.target.id]=Number(e.target.value);e.target.nextElementSibling.textContent=e.target.value+(e.target.id.endsWith('Volume')?' %':e.target.id==='fov'?'°':'×');if(e.target.id.endsWith('Volume'))soundscape.setVolumes(model.s.settings);else world.applyViewSettings()}});
