let lookPending=false,ignoreLookDelta=false;
function requestLook(){
 if(!playing||screen||document.pointerLockElement===$('world')||lookPending||matchMedia('(pointer: coarse)').matches)return;
 if(!$('world').requestPointerLock)return;
 lookPending=true;
 try{const result=$('world').requestPointerLock();result?.catch(()=>{lookPending=false;showLookHint()})}catch{lookPending=false;showLookHint()}
}
function showLookHint(){if(playing&&!screen)toast('Maus bewegen zum Umschauen. Für freie Drehung einmal ins Spiel klicken.');}
function releaseLook(){if(document.pointerLockElement===$('world'))document.exitPointerLock();drag=null;}
function rotateLook(dx,dy){if(!world||!playing||screen)return;world.angle-=clamp(dx,-120,120)*.0027*(model.s.settings.sensitivity||1);world.pitch=clamp(world.pitch+clamp(dy,-120,120)*.0022*(model.s.settings.sensitivity||1),.06,.95)}
document.addEventListener('pointerlockchange',()=>{
 lookPending=false;ignoreLookDelta=true;
 if(document.pointerLockElement!==$('world')&&playing&&!screen){save();open('menu')}
});
document.addEventListener('pointerlockerror',()=>{lookPending=false;showLookHint()});
document.addEventListener('mousemove',e=>{if(document.pointerLockElement!==$('world'))return;if(ignoreLookDelta){ignoreLookDelta=false;return}rotateLook(e.movementX,e.movementY)});
$('world').addEventListener('pointerdown',e=>{
 if(screen||!playing)return;
 if(e.pointerType==='mouse'){requestLook();return}
 drag={x:e.clientX,y:e.clientY};$('world').setPointerCapture(e.pointerId);
});
$('world').addEventListener('pointermove',e=>{
 if(screen||!playing)return;
 if(e.pointerType==='mouse'){if(!document.pointerLockElement&&!lookPending)rotateLook(e.movementX,e.movementY);return}
 if(!drag)return;rotateLook((e.clientX-drag.x)*2,(e.clientY-drag.y)*2);drag={x:e.clientX,y:e.clientY};
});
for(const type of ['pointerup','pointercancel','lostpointercapture'])$('world').addEventListener(type,()=>drag=null);
$('world').addEventListener('wheel',e=>{if(!playing||screen)return;e.preventDefault();world.distance=clamp(world.distance+e.deltaY*.01,3,14)},{passive:false});
for(const b of document.querySelectorAll('[data-key]')){b.addEventListener('pointerdown',e=>{e.preventDefault();keys[b.dataset.key]=true;b.setPointerCapture(e.pointerId)});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>keys[b.dataset.key]=false)}
function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-last)/1000,.25);last=now;if(document.hidden)return;let active=playing&&!screen;if(active){const wasOpen=model.s.cafe?.phase==='open';const priorInteraction=model.s.job?.interaction,priorDaily=model.s.dailyLife.action,priorWorkshop=model.s.workshop?.active?.action;model.updateTime(dt);if(priorWorkshop&&!model.s.workshop?.active?.action){keys={};save();}if(priorDaily&&!model.s.dailyLife.action){world.cameraRig.reset();keys={};save();}if(priorInteraction&&!model.s.job?.interaction){waypoint=model.s.job?'job':null;save();}if(wasOpen&&model.s.cafe.phase==='closed'){toast('Schicht beendet. Das Team macht Feierabend. Den Bericht findest du im Betriebsbuch.','success');save();}}let movement=world.update(dt,keys,active);soundscape.update(dt,model.s,world,movement,active);if(active){saveTimer+=dt;if(saveTimer>30){saveTimer=0;save()}}hudTimer+=dt;if(hudTimer>.15){hudTimer=0;hud()}}
try{world=new World($('world'),model);$('loading').classList.add('hidden');$('start').classList.remove('hidden');hud();requestAnimationFrame(frame)}catch(err){$('loading').innerHTML='<span class="brand">ZERO <i>//</i> RISE</span><p>Die 3D-Ansicht konnte nicht starten.</p><p style="max-width:450px;text-align:center;padding:20px;font-size:14px;line-height:1.7">Aktiviere die Hardwarebeschleunigung in deinem Browser und öffne das Spiel anschließend erneut in Chrome, Edge oder Firefox.</p>';console.error(err)}

function cafeHoursMarkup(s){const h=cafeHours(s);return `<div class="cafe-hours ${h.tone}"><strong>${h.state}</strong><span>${h.detail}</span></div>`}
function cafeTraining(b,c){
 const roles=['Barista','Service','Abräumkraft'],levels=b.staffLevels||[1,1,1],locked=c.phase==='open';
 return '<h3 class="section-title">Ausbildung für dein Team</h3><p class="footnote">Stufe 2: +50 % Arbeitstempo, Gehtempo 1,65 m/s. Stufe 3: +110 % Arbeitstempo, Gehtempo 2,15 m/s. Stufe 1 geht mit 1,15 m/s. Die Ausbildung wirkt im gesamten laufenden Cafébetrieb, auch während deiner Abwesenheit. Der Lohn bleibt bei 3,75 € je Einsatzstunde, mindestens zwei Stunden pro Öffnung. Beim Entlassen geht die Ausbildung dieser Person verloren.</p><div class="cards">'+roles.map((role,i)=>{
  const level=levels[i],hired=i<b.staff;
  return '<article class="card"><span class="tag">'+(hired?'STUFE '+level+' / 3':'UNBESETZT')+'</span><h3>'+role+'</h3><p>'+['Zubereitung an der Maschine.','Bestellungen aufnehmen, servieren und kassieren.','Benutzte Gedecke abräumen.'][i]+'</p>'+button(!hired?'Zuerst einstellen':level===3?'Voll ausgebildet':'Ausbilden · '+euro(STAFF_TRAINING_COST[level]),'manage','cafe|train|'+i,'secondary',!hired||level>=3||locked||model.s.money<STAFF_TRAINING_COST[level])+'</article>';
 }).join('')+'</div>'+(locked?'<p class="footnote">Ausbildung ist nach dem Ende deiner Schicht möglich.</p>':'');
}
function cafeDayReport(r){
 if(r.economyModel!==2)return '<h3 class="section-title">Ältere Tagesabrechnung · Tag '+r.day+'</h3><p class="lead">Umsatz '+euro(r.sales)+' · Kosten '+euro(r.costs)+' · Ergebnis '+euro(r.profit)+'. Dieser Tag wurde nach den bisherigen Regeln abgerechnet.</p>';
 return '<h3 class="section-title">Tagesabrechnung · Tag '+r.day+'</h3><div class="rows">'+row('Gästeumsatz',r.manualMinutes+' Spielminuten Betrieb · einschließlich Trinkgeld',euro(r.sales))+row('Zutaten','Jede begonnene Zubereitung, auch verworfene',euro(r.ingredients))+row('Personal','3,75 € / Einsatzstunde je Person · mindestens 2 Stunden',euro(r.wages))+row('Fixkosten','Miete und laufende Grundkosten · täglich',euro(r.overhead))+row('Werbung','Für diesen Betriebstag',euro(r.advertising))+row('Verbrauchsmaterial','Vorratspaket, bereits beim Einkauf bezahlt',euro(r.supplies))+row('Betriebsergebnis','Umsatz minus sämtliche Betriebskosten',euro(r.profit))+row('Bargeldbuchung um Mitternacht','Bereits bezahltes Verbrauchsmaterial wird nicht doppelt abgezogen',euro(r.cashMovement))+'</div>';
}
function cafeEconomyNote(r){
 const cost=r.breakdown,contribution=r.served?(r.sales+r.tips-cost.ingredients)/r.served:0;
 const gap=r.profit<0&&contribution>0?Math.ceil(-r.profit/contribution):null;
 return '<div class="info-box"><b>'+ (r.profit>=0?'Der Betriebstag deckt seine Kosten.':'Der Betriebstag deckt seine Kosten noch nicht.')+'</b><br>'+ (gap?'Bei gleichem Bestellmix hätten ungefähr '+gap+' zusätzliche bezahlte Bestellungen gefehlt. Das ist ein Richtwert, keine Umsatzgarantie. ':r.profit<0?'Es fehlen ausreichend bezahlte Bestellungen. ':'Der Überschuss steht für Rücklagen und Investitionen zur Verfügung. ')+'Sechs Sitzplätze begrenzen den Umsatz. Drei Mitarbeiter lohnen sich erst bei ausreichender Auslastung. Ausbildung verbessert die Bedienung; Qualität, Preisniveau und Wirtschaftslage bestimmen die Nachfrage. Ein später Start verkürzt den Verkaufstag, die Fixkosten bleiben gleich.</div>';
}

function cafePatienceMarkup(g){
 if(!['order','accepted'].includes(g.stage))return '';
 const v=guestServiceView(g),percent=Math.round(v.fraction*100);
 return '<div class="cafe-patience'+(v.urgent?' urgent':'')+'" style="--patience:'+v.color+'"><div><span>'+(v.urgent?'Geht bald':'Verbleibende Geduld')+'</span><strong>'+v.seconds+' Spielmin.</strong></div><progress max="100" value="'+percent+'" aria-label="Verbleibende Geduld: '+v.seconds+' Spielminuten"></progress></div>';
}

function performCafeGuest(id){
 const g=model.s.cafe.guests.find(g=>g.id===id);if(!g)return false;
 const kind=g.stage==='order'?'cafeOrder':g.stage==='paying'?'cafePay':'cafeServe';
 if(!model.cafeAction('guest',id))return false;
 const seat=guestSeat(g.seat,g.side);world.player.rotation.y=Math.atan2(seat.x-model.s.position.x,seat.z-model.s.position.z);world.gesture(kind);return true;
}
function cafeReportContent(r){
 if(!r)return '<p class="lead">Nach deiner ersten Schicht erscheint hier der Bericht.</p>';
 const m=r.service,sec=n=>n==null?'—':Math.round(n)+' Spielmin.',moneyRows=r.breakdown?row('Zutaten','Tatsächlich für Bestellungen eingesetzt',euro(r.breakdown.ingredients))+row('Personal',r.economyModel===2?'3,75 € / Stunde je Person · mindestens 2 Stunden':'Zeitanteilige Löhne deiner Schicht',euro(r.breakdown.wages))+row('Fixkosten und Werbung',r.economyModel===2?'Vollständige Tageskosten':'Zeitanteil innerhalb des Betriebstages',euro(r.breakdown.overhead+r.breakdown.advertising))+(r.breakdown.supplies!=null?row('Verbrauchsmaterial','Vorratspaket · bereits beim Einkauf bezahlt',euro(r.breakdown.supplies)):''):row('Kosten','Älterer Schichtbericht',euro(r.costs));
 let content='<div class="report-heading"><span class="tag">TAG '+r.day+'</span><span>'+esc(r.reason)+(r.duration!=null?' · '+Math.round(r.duration)+' Spielminuten Schichtdauer':'')+'</span></div>';
 if(m){
  content+=(m.partial?'<div class="info-box">Diese Schicht wurde mit einem älteren Spielstand begonnen. Die Servicewerte erfassen nur den Abschnitt seit dem Update; die Geldbeträge gelten für die gesamte Schicht. Ab der nächsten Schicht wird vollständig gemessen.</div>':'');
  content+='<div class="stats-grid report-stats">'+stat('Ø bis zum Servieren',sec(m.averageWait))+stat('Zufrieden bedient',m.served?m.satisfied+' / '+m.served:'—')+stat('Bedienquote',m.completion==null?'—':m.completion+' %')+'</div>';
  content+='<p class="footnote">Die Wartezeit zählt ab dem Sitzen bis zum Servieren und nur für bediente Gäste. Zufrieden bedeutet: innerhalb der ersten Hälfte ihrer Geduldszeit bedient. Die Bedienquote berücksichtigt auch unbediente Gäste. Pausen und Menüs zählen nicht mit.</p>';
  content+='<div class="rows">'+row('Bedient','Du: '+m.playerServed+' · Service: '+m.staffServed,String(m.served))+row('Längste Wartezeit','Unter den bedienten Gästen',m.served?sec(m.maxWait):'—')+row('Wegen Wartezeit gegangen','Geduld vor dem Servieren aufgebraucht',String(m.timedOut))+row('Bei Schluss noch unbedient','Schichtende oder vorzeitiges Schließen',String(m.closedUnserved))+'</div>';
  const roles=['Barista','Service','Abräumkraft'],team=r.team.staff?roles.slice(0,r.team.staff).map((role,i)=>role+' · Stufe '+r.team.levels[i]).join(' / '):'Du hast ohne Mitarbeiter gearbeitet.';
  content+='<h3 class="section-title">Dein Team in dieser Schicht</h3><p class="lead">'+team+'</p><div class="rows">'+row('Barista','Zubereitungen begonnen',String(m.preparedByStaff))+row('Service','Bestellungen aufgenommen: '+m.ordersByStaff+' · Gäste bedient: '+m.staffServed+' · Rechnungen kassiert: '+m.payments.staff,'')+row('Abräumkraft','Gedecke vollständig abgeräumt',String(m.clearedByStaff))+'</div>';
  let advice=!m.served&&!m.timedOut&&!m.closedUnserved?'Noch keine abgeschlossenen Gästebesuche für eine Bewertung.':m.timedOut?'Einige Gäste haben zu lange gewartet. Nutze die nach Restzeit sortierte Bestellliste und bringe fertige Tabletts zügig zum Gast.':m.closedUnserved?'Beim Schließen waren noch Gäste unbedient. Ein vorzeitiger Feierabend verkürzt ihre mögliche Bedienzeit.':m.served&&m.satisfied<m.served?'Alle erfassten Gäste wurden bedient. Einige warteten länger als die Hälfte ihrer Geduldszeit. Prüfe anhand der Teamaufgaben, wo du mithelfen kannst.':'Alle erfassten Gäste wurden rechtzeitig und innerhalb der ersten Hälfte ihrer Geduldszeit bedient.';
  content+='<div class="info-box"><b>Hinweis für die nächste Schicht</b><br>'+advice+'</div>';
 }else content+='<div class="info-box">Für diese ältere Schicht wurden noch keine Wartezeiten oder Teamaufgaben erfasst. Die vorhandene Abrechnung bleibt erhalten.</div>';
 content+='<h3 class="section-title">Schichtabrechnung</h3><div class="rows">'+row('Speisen und Getränke','Abgerechneter Umsatz',euro(r.sales))+row('Trinkgeld','Zusätzlich zum Umsatz',euro(r.tips))+moneyRows+row('Ergebnis','Umsatz + Trinkgeld − Schichtkosten','<strong class="'+(r.profit>=0?'positive':'negative')+'">'+euro(r.profit)+'</strong>')+'</div>';
 if(m)content+='<p class="footnote">Rechnungen: '+m.payments.player+' von dir kassiert · '+m.payments.staff+' vom Service · '+m.payments.table+' passend hinterlassen · '+m.payments.closing+' beim Schichtende abgewickelt.</p>';
 return content+(r.economyModel===2?cafeEconomyNote(r):'')+'<p class="footnote">'+(r.economyModel===2?'Der Bericht enthält alle Betriebskosten dieses Tages. Das Vorratspaket zählt zum Gewinn, wird um Mitternacht aber nicht noch einmal bezahlt. Ausbildung und Einstellungen sind einmalige Investitionen und stehen außerhalb des Betriebsergebnisses.':'Älterer Bericht: anteilige Tageskosten und pauschaler Restbetrieb nach den damaligen Regeln.')+' Auszahlung erfolgt um Mitternacht.</p><div class="button-row">'+button('Zurück ins Spiel','close')+button('Café verwalten','business','cafe','secondary')+'</div>';
}
